86			return new PropertyMapper(this, operator);
87		}
88	
89		/**
90		 * Return a new {@link Source} from the specified value that can be used to perform
91		 * the mapping.
92		 * @param <T> the source type
93		 * @param value the value
94		 * @return a {@link Source} that can be used to complete the mapping
95		 */
96		public <T> Source<T> from(@Nullable T value) {
97			return from(() -> value);
98		}
99	
100		/**
101		 * Return a new {@link Source} from the specified value supplier that can be used to
102		 * perform the mapping.
103		 * @param <T> the source type
104		 * @param supplier the value supplier
105		 * @return a {@link Source} that can be used to complete the mapping
106		 * @see #from(Object)
107		 */
108		public <T> Source<T> from(Supplier<? extends @Nullable T> supplier) {
109			Assert.notNull(supplier, "'supplier' must not be null");
110			Source<T> source = getSource(supplier);
111			if (this.sourceOperator != null) {
112				source = this.sourceOperator.apply(source);
113			}
114			return source;
115		}
116	
117		private <T> Source<T> getSource(Supplier<? extends @Nullable T> supplier) {
118			if (this.parent != null) {
119				return this.parent.from(supplier);
120			}
121			return new Source<>(SingletonSupplier.of(supplier), (value) -> true);
122		}
123	
124		/**
125		 * Return the property mapper.
126		 * @return the property mapper
127		 */
128		public static PropertyMapper get() {
129			return INSTANCE;
130		}
131	
132		/**
133		 * An operation that can be applied to a {@link Source}.
134		 */
135		@FunctionalInterface
136		public interface SourceOperator {
137	
138			/**
139			 * Apply the operation to the given source.
140			 * @param <T> the source type
141			 * @param source the source to operate on
142			 * @return the updated source
143			 */
