41	class StartupInfoLogger {
42	
43		private final @Nullable Class<?> sourceClass;
44	
45		private final Environment environment;
46	
47		StartupInfoLogger(@Nullable Class<?> sourceClass, Environment environment) {
48			this.sourceClass = sourceClass;
49			this.environment = environment;
50		}
51	
52		void logStarting(Log applicationLog) {
53			Assert.notNull(applicationLog, "'applicationLog' must not be null");
54			applicationLog.info(LogMessage.of(this::getStartingMessage));
55			applicationLog.debug(LogMessage.of(this::getRunningMessage));
56		}
57	
58		void logStarted(Log applicationLog, Startup startup) {
59			if (applicationLog.isInfoEnabled()) {
60				applicationLog.info(getStartedMessage(startup));
61			}
62		}
63	
64		private CharSequence getStartingMessage() {
65			StringBuilder message = new StringBuilder();
66			message.append("Starting");
67			appendAotMode(message);
68			appendApplicationName(message);
69			appendApplicationVersion(message);
70			appendJavaVersion(message);
71			appendPid(message);
72			appendContext(message);
73			return message;
74		}
75	
76		private CharSequence getRunningMessage() {
77			StringBuilder message = new StringBuilder();
78			message.append("Running with Spring Boot");
79			appendVersion(message, getClass());
80			message.append(", Spring");
81			appendVersion(message, ApplicationContext.class);
82			return message;
83		}
84	
85		private CharSequence getStartedMessage(Startup startup) {
86			StringBuilder message = new StringBuilder();
87			message.append(startup.action());
88			appendApplicationName(message);
89			message.append(" in ");
90			message.append(startup.timeTakenToStarted().toMillis() / 1000.0);
91			message.append(" seconds");
92			Long uptimeMs = startup.processUptime();
93			if (uptimeMs != null) {
94				double uptime = uptimeMs / 1000.0;
95				message.append(" (process running for ").append(uptime).append(")");
96			}
97			return message;
98		}
99	
100		private void appendAotMode(StringBuilder message) {
101			append(message, "", () -> AotDetector.useGeneratedArtifacts() ? "AOT-processed" : null);
102		}
103	
104		private void appendApplicationName(StringBuilder message) {
105			append(message, "",
106					() -> (this.sourceClass != null) ? ClassUtils.getShortName(this.sourceClass) : "application");
107		}
108	
109		private void appendVersion(StringBuilder message, Class<?> source) {
110			append(message, "v", () -> source.getPackage().getImplementationVersion());
111		}
112	
113		private void appendApplicationVersion(StringBuilder message) {
114			append(message, "v", () -> this.environment.getProperty("spring.application.version"));
115		}
116	
117		private void appendPid(StringBuilder message) {
118			append(message, "with PID ", () -> this.environment.getProperty("spring.application.pid"));
119		}
120	
121		private void appendContext(StringBuilder message) {
122			StringBuilder context = new StringBuilder();
123			ApplicationHome home = new ApplicationHome(this.sourceClass);
124			if (home.getSource() != null) {
125				context.append(home.getSource().getAbsolutePath());
126			}
127			append(context, "started by ", () -> System.getProperty("user.name"));
128			append(context, "in ", () -> System.getProperty("user.dir"));
129			if (!context.isEmpty()) {
130				message.append(" (");
131				message.append(context);
132				message.append(")");
133			}
134		}
135	
136		private void appendJavaVersion(StringBuilder message) {
137			append(message, "using Java ", () -> System.getProperty("java.version"));
138		}
139	
140		private void append(StringBuilder message, String prefix, Callable<@Nullable Object> call) {
141			append(message, prefix, call, "");
142		}
143	
144		private void append(StringBuilder message, String prefix, Callable<@Nullable Object> call, String defaultValue) {
145			Object result = callIfPossible(call);
146			String value = (result != null) ? result.toString() : null;
147			if (!StringUtils.hasLength(value)) {
148				value = defaultValue;
149			}
150			if (StringUtils.hasLength(value)) {
151				message.append((!message.isEmpty()) ? " " : "");
152				message.append(prefix);
153				message.append(value);
154			}
155		}
156	
157		private @Nullable Object callIfPossible(Callable<@Nullable Object> call) {
158			try {
159				return call.call();
160			}
161			catch (Exception ex) {
162				return null;
163			}
164		}
165	
166	}
